"""STOP-EV vs TOP MAKERS (2026-11-16, session aea5bfb9; USER: "We have some results for comparison generated by codex research session, it
looks stop-ev model currently generates the optimal result and the 1st minute markout pnl looks good, check the result and how it compares
against top makers?"). POST HOC and descriptive: no readings, no verdicts.

OURS (simulated; read, not re-run): the strategy scorecard's frozen fill ledgers (Codex; freeze 819e59fe, results d365caa5;
strategy_scorecard_20261116_v1/<day>/fills.parquet): STOP_EV / v3 / recorded58 (primary: the recorded order-latency medians 58 / 37 ms) and
STOP_EV / legacy40 (40 / 22 ms); review 50 ms, M50, queue M with unknown depth 0, 6 rungs x 30 sh a side; all fills, and fills on orders
>= 100 ms old (B1a: replay young fills are mostly phantom on live orders).
THEIRS (real): every maker leg on the public tape in the same 1,434 first-minute windows - the scorecard's own window loop (M.P1.window_pairs,
M.boundary_cut: six 10-31 boundary windows out; the imputed-untimed tape of pf_stop_ev.impute_window) - with anchor in [ws, te) (the first
60 s); makers ranked per day by shares in t_rel 0-240 s (B12 / GAP / TOP-COMPARE's rule, pf_gap_top_makers.rank_groups): top 5, ranks 6-20,
rest.
ONE VALUE FUNCTION FOR BOTH (pf_strategy_metrics' conventions): fill time = anchor - 50 ms (M50); pre-fill mid = the last valid book mid
strictly before the fill time; markouts at fill + 100 / 500 / 1,000 / 5,000 ms (the last valid mid at or before); terminal = the window's
60.2 s mark (the scorecard's terminal_mid_cents); settlement = the recorded binary outcome (settlement_yes): each fill held to resolution;
source WS / E2 / imputed (the anchor of the taker order); depth at the fill = ticks behind the maker side's best in the frame strictly before
the anchor (pf_gap_top_makers.depth_of, TOP-COMPARE's classifier). A maker leg without a valid mid before its fill time is a status (counted),
never valued.
CONTROLS (any failure -> no output): (1) the value function applied to the scorecard's recorded58 and legacy40 STOP_EV fills reproduces the
ledger's fill time, pre-fill mid, spread, four markouts, terminal and settlement for every fill (|diff| <= 1e-9); (2) planted errors that (1)
catches: on a synthetic book no M50 shift, the pre-fill mid at-or-before and the ask sign flipped; on each real day no M50 shift and the ask
sign flipped (at-or-before differs from strictly-before only where a fill time equals a frame time: counted, not required); (3) tape identity
on every window-side, the imputed legs equal STOP-EV-PLAY v2's count for the same windows, the windows equal the scorecard's (day, m) set; (4)
TOP-COMPARE's anchor-based 1 s value recomputed on its population (timed legs with a depth frame and a finite 1 s mid) equals its saved
top 5 / 6-20 / rest sums on every date without boundary exclusions.
LIMITS: ours simulated (rule M / queue M, unknown depth 0, young fills B1a, inflated volumes C4); theirs real but valued per fill, which is
not account P&L - their later-minute trading, hedges and unwinds are not seen, so their 'settlement' is what holding THESE fills to
resolution would give; consumed days; first minute only; signer ids per day (our own account, if it traded on these days, is among the
ranked makers); fees and rewards not counted.
Usage (run_light, PF_SLOT=claude): pf_stop_ev_vs_top.py selftest | day <day> | report; driver run_stop_ev_vs_top.sh
"""
import json
import os
import sys
import time

import numpy as np
import pandas as pd

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import pf_stop_ev_play as P                               # noqa: E402
import pf_gap_top_makers as GP                            # noqa: E402

V, E, M, K = P.V, P.E, P.M, P.K
DAYS = ('20261027', '20261031', '20261101', '20261102', '20261103')
SC = f'{K.IO}/strategy_scorecard_20261116_v1'
PLAY2 = f'{K.IO}/stop_ev_play2_20261115'
TOPC = f'{K.IO}/top_compare_20261114'
OUTD = f'{K.IO}/stop_ev_vs_top_20261116'
CHECKED = ('STOP_EV__recorded58', 'STOP_EV__legacy40')    # valued on the recorded books (zero_all is valued on its zero-feed books)
SHIFT = 50.0; HS = (100, 500, 1000, 5000)
GROUPS = ('top 5', '6-20', 'rest')
VCOLS = ['spread_capture_usd'] + [f'markout_{h}_usd' for h in HS] + ['terminal_pnl_usd', 'settlement_pnl_usd']
TOL = 1e-9; MEM_CAP_MIB = 2048.0
MUT_NOSHIFT = MUT_PRE_AT = MUT_ASKSIGN = 0                # planted errors (selftest and the first-window check only)


def book_mids(W):
    """The scorecard's valuation book: valid frames (bid >= 0, ask > bid) of the window's shared frame clock."""
    tf = np.asarray(W[0]['tf'], float); bb = W[0]['P5'][:, 0]; ba = W[1]['P5'][:, 0]
    good = (bb >= 0) & (ba > bb)
    return tf[good], (bb[good] + ba[good]) / 2.0


def lookup(times, mids, q, before=False):
    ix = np.searchsorted(times, q, side='left' if before else 'right') - 1
    return np.where(ix >= 0, mids[np.maximum(ix, 0)], np.nan)


def value(times, mids, anc, side, p, q, term_mark, y):
    """Per fill, the scorecard's conventions: fill time, pre-fill mid, spread, markouts, terminal and settlement ($)."""
    anc = np.asarray(anc, float); p = np.asarray(p, float); q = np.asarray(q, float)
    sg = np.where(np.asarray(side) == 0, 1.0, 1.0 if MUT_ASKSIGN else -1.0)
    t = anc - (0.0 if MUT_NOSHIFT else SHIFT)
    pre = lookup(times, mids, t, before=not MUT_PRE_AT)
    out = dict(fill_ms=t, pre_mid_cents=pre, spread_capture_usd=q * sg * (pre - p) / 100.0)
    for h in HS:
        out[f'markout_{h}_usd'] = q * sg * (lookup(times, mids, t + h) - p) / 100.0
    out['terminal_pnl_usd'] = q * sg * (np.asarray(term_mark, float) - p) / 100.0
    out['settlement_pnl_usd'] = q * sg * (np.asarray(y, float) - p / 100.0)
    return out


def parity(F, times, mids):
    """Control (1): the value function on the scorecard's own fills; returns the number of fills that differ."""
    if not len(F):
        return 0
    v = value(times, mids, F.anchor_ms.values, F.side.values, F.price_cents.values, F.shares.values, F.terminal_mid_cents.values,
              F.settlement_yes.values)
    bad = ~np.isclose(v['fill_ms'], F.fill_ms.values, rtol=0, atol=TOL) | ~np.isclose(v['pre_mid_cents'], F.pre_mid_cents.values, rtol=0, atol=TOL)
    for c in VCOLS:
        bad |= ~np.isclose(v[c], F[c].values, rtol=0, atol=TOL)
    return int(bad.sum())


def dclass(d):
    if d is None:
        return 'no frame'
    return 'inside' if d < 0 else ('at best' if d == 0 else ('1 behind' if d == 1 else '2+ behind'))


def synthetic():
    """A toy book and three fills with values worked by hand; returns the failures."""
    times = np.array([0.0, 100.0, 200.0, 1300.0]); mids = np.array([50.0, 51.0, 52.0, 55.0])
    # bid 10 sh @ 50 anchored 150 (fill 100: pre = mid strictly before 100 = 50), ask 10 sh @ 53 anchored 250 (fill 200: pre 51)
    v = value(times, mids, [150.0, 250.0], [0, 1], [50.0, 53.0], [10.0, 10.0], 54.0, 1.0)
    want = dict(fill_ms=[100.0, 200.0], pre_mid_cents=[50.0, 51.0], spread_capture_usd=[0.0, 0.2], markout_100_usd=[0.2, 0.1],
                markout_1000_usd=[0.2, 0.1], markout_5000_usd=[0.5, -0.2], terminal_pnl_usd=[0.4, -0.1], settlement_pnl_usd=[5.0, -4.7])
    return [k for k, w in want.items() if not np.allclose(v[k], w, rtol=0, atol=1e-12)]


def selftest():
    bad = synthetic(); caught = {}
    for nm in ('MUT_NOSHIFT', 'MUT_PRE_AT', 'MUT_ASKSIGN'):
        globals()[nm] = 1
        try:
            caught[nm] = bool(synthetic())
        finally:
            globals()[nm] = 0
    if [dclass(x) for x in (None, -1, 0, 1, 3)] != ['no frame', 'inside', 'at best', '1 behind', '2+ behind']:
        bad.append('depth class')
    bad += list(GP.selftest() or [])
    if bad or not all(caught.values()):
        sys.exit(f'STOP-EV-VS-TOP SELFTEST FAILED -> no output: {bad}, planted errors caught {caught}')
    print(f'stop-ev-vs-top selftests passed; planted errors caught: {caught}', flush=True)
    return caught


def day_run(day):
    if day not in DAYS:
        sys.exit(f'REFUSED: {day} is not one of the scorecard dates')
    selftest(); T0 = time.time()
    OF = pd.read_parquet(f'{SC}/{day}/fills.parquet')
    SW = pd.read_parquet(f'{SC}/{day}/windows.parquet', columns=['day', 'm', 'case', 'terminal_mid_cents', 'settlement_yes'])
    marks = SW.drop_duplicates(['m']).set_index('m')
    if SW.groupby('m').terminal_mid_cents.nunique().max() != 1 or SW.groupby('m').settlement_yes.nunique().max() != 1:
        sys.exit('REFUSED: the scorecard cases disagree on a window mark or outcome')
    p2 = json.load(open(f'{PLAY2}/test_{day}.json'))['stat']
    D = K.load_day(day); S1d = f'{K.IO}/step1/{day}'
    full = pd.read_parquet(f'{S1d}/legs_timed2.parquet', columns=['mid', 'signer', 'shares', 't_rel'])
    tk = pd.read_parquet(f'{S1d}/legs_tk.parquet', columns=['tk']).tk.values
    if len(tk) != len(full):
        sys.exit('REFUSED: legs_tk not aligned with legs_timed2')
    inw = full.mid.isin(list(D['W0'])).values
    G = GP.rank_groups(full.signer.values[inw], full.shares.values[inw].astype(float), full.t_rel.values[inw].astype(float))
    SIG = full.signer.values.astype('int64'); del full
    LT = D['LT']; ix = LT.index.values; grp = np.where(tk[ix] >= 0, tk[ix], -1 - ix)
    WSg = pd.Series(M.TS.ws_groups(LT.how.values, grp), index=LT.index); GRP = pd.Series(grp, index=LT.index)
    RW, ust = E.raw_windows(day, D); cut = M.boundary_cut(day)
    st = dict(windows=0, boundary_windows=0, imputed_legs=0, legs=0, no_pre_mid=0, no_mark=0, parity_fills=0, parity_bad=0,
              mutations={nm: 0 for nm in ('MUT_NOSHIFT', 'MUT_PRE_AT', 'MUT_ASKSIGN')}, topc_legs=0)
    acc = {}; ours = {}; topc = {g: 0.0 for g in GROUPS}; pm = {}; seen = []
    for W in M.P1.window_pairs(D):
        if W[0]['ws'] < cut:
            st['boundary_windows'] += 1; continue
        m = int(W[0]['m']); seen.append(m); LR = {}; SR = {}; GR = {}
        for s in (0, 1):
            if (m, s) in D['LI']:
                g = LT.iloc[D['LI'][(m, s)]]; o = np.lexsort(((-g.ptick.values if s == 0 else g.ptick.values), g.anc.values)); lr = g.index.values[o]
            else:
                lr = np.zeros(0, dtype=int)
            if len(lr) != len(W[s]['anc']) or not np.array_equal(LT.loc[lr, 'anc'].values, W[s]['anc']):
                sys.exit(f'STOP-EV-VS-TOP CONTROL FAILED on {day} window {m}: tape identity -> no output')
            LR[s] = lr; SR[s] = WSg.reindex(lr).values.astype(bool); GR[s] = GRP.reindex(lr).values.astype('int64')
        # control (4) population: TOP-COMPARE's timed tape, valued on the frame clock tf_mff at the anchor + 1 s
        for s in (0, 1):
            sg = 1.0 if s == 0 else -1.0; tf, mff = W[s]['tf_mff']; tf = np.asarray(tf, float); tfl = tf.tolist()
            for i, a in enumerate(W[s]['anc']):
                a = float(a)
                if not (W[0]['ws'] <= a < W[0]['te']):
                    continue
                p = int(W[s]['ptl'][i])
                if dclass(GP.depth_of(tfl, W[s]['P5'], W[s]['opp'], s, a, p)) == 'no frame':
                    continue
                v1 = sg * (mff[max(int(np.searchsorted(tf, a + 1000.0, side='right')) - 1, 0)] - p)
                if np.isfinite(v1):
                    topc[G.get(int(SIG[LR[s][i]]), 'rest')] += float(W[s]['shl'][i]) * v1; st['topc_legs'] += 1
        W, LR, SR, GR, IM = E.impute_window(W, LR, SR, GR, RW.get(m, {}).get('imp', []), ust['imp_off_ms'])
        st['windows'] += 1; st['imputed_legs'] += sum(int(IM[s].sum()) for s in (0, 1))
        times, mids = book_mids(W); tm = float(marks.loc[m, 'terminal_mid_cents']); y = float(marks.loc[m, 'settlement_yes'])
        tfl = np.asarray(W[0]['tf'], float).tolist()
        # ours: control (1) on the checked cases, then the same splits as theirs
        F = OF[OF.m == m]
        for case in CHECKED:
            Fc = F[F.case == case]; st['parity_fills'] += len(Fc); st['parity_bad'] += parity(Fc, times, mids)
            for nm in st['mutations']:
                globals()[nm] = 1
                try:
                    st['mutations'][nm] += parity(Fc, times, mids)
                finally:
                    globals()[nm] = 0
        for r in F.itertuples(index=False):
            s = int(r.side); d = dclass(GP.depth_of(tfl, W[s]['P5'], W[s]['opp'], s, float(r.anchor_ms), float(r.price_cents)))
            src = 'WS' if r.ws_timed else ('imputed' if r.imputed else 'E2')
            e = ours.setdefault((r.case, bool(r.age_ms < 100.0), src, d), np.zeros(2 + len(VCOLS)))
            e[0] += 1; e[1] += r.shares
            for j, c in enumerate(VCOLS):
                e[2 + j] += getattr(r, c)
        # theirs: every maker leg in the first 60 s of the imputed tape
        for s in (0, 1):
            a_ = np.asarray(W[s]['anc'], float); sel = np.flatnonzero((a_ >= W[0]['ws']) & (a_ < W[0]['te']))
            if not len(sel):
                continue
            v = value(times, mids, a_[sel], np.full(len(sel), s), np.asarray(W[s]['ptl'], float)[sel], np.asarray(W[s]['shl'], float)[sel], tm, y)
            ok = np.isfinite(v['pre_mid_cents'])
            for c in VCOLS:
                ok &= np.isfinite(v[c])
            st['legs'] += len(sel); st['no_pre_mid'] += int((~np.isfinite(v['pre_mid_cents'])).sum()); st['no_mark'] += int((~ok).sum())
            opp = W[s]['opp']
            for n, i in enumerate(sel):
                if not ok[n]:
                    continue
                sig = int(SIG[LR[s][i]]); who = G.get(sig, 'rest')
                src = 'WS' if SR[s][i] else ('imputed' if IM[s][i] else 'E2')
                d = dclass(GP.depth_of(tfl, W[s]['P5'], opp, s, float(a_[i]), float(W[s]['ptl'][i])))
                q = float(W[s]['shl'][i])
                e = acc.setdefault((who, src, d), np.zeros(2 + len(VCOLS)))
                e[0] += 1; e[1] += q
                for j, c in enumerate(VCOLS):
                    e[2 + j] += v[c][n]
                if who == 'top 5':
                    e2 = pm.setdefault((sig, src), np.zeros(2 + len(VCOLS))); e2[0] += 1; e2[1] += q
                    for j, c in enumerate(VCOLS):
                        e2[2 + j] += v[c][n]
        if st['windows'] % 48 == 0:
            r2 = K.rss_mib(); print(f'{day}: {st["windows"]} windows, {time.time() - T0:.0f} s, rss {r2:.0f} MiB', flush=True)
            if r2 > MEM_CAP_MIB:
                sys.exit(f'REFUSED: resident memory {r2:.0f} MiB > {MEM_CAP_MIB:.0f} MiB')
    # controls (1)-(4)
    fails = []
    if st['parity_bad'] or not st['parity_fills']:
        fails.append(f"value parity: {st['parity_bad']} of {st['parity_fills']} scorecard fills differ")
    if not (st['mutations']['MUT_NOSHIFT'] and st['mutations']['MUT_ASKSIGN']):
        fails.append(f"planted errors not caught on the real fills: {st['mutations']}")
    if st['imputed_legs'] != int(p2['imputed_legs']):
        fails.append(f"imputed legs {st['imputed_legs']} vs STOP-EV-PLAY v2 {p2['imputed_legs']}")
    if sorted(seen) != sorted(marks.index.astype(int).tolist()) or len(seen) != len(set(seen)):
        fails.append('windows differ from the scorecard (day, m) set')
    if not st['boundary_windows']:
        T = pd.read_parquet(f'{TOPC}/theirs_{day}.parquet'); ref = T.groupby('who').v1.sum()
        st['topc'] = {g: [topc[g], float(ref.get(g, 0.0))] for g in GROUPS}
        if any(abs(topc[g] - float(ref.get(g, 0.0))) > 1e-6 * max(1.0, abs(float(ref.get(g, 0.0)))) for g in GROUPS):
            fails.append(f"TOP-COMPARE recomputation differs: {st['topc']}")
    else:
        st['topc'] = 'not comparable (boundary windows excluded here, not in TOP-COMPARE)'
    if fails:
        sys.exit(f'STOP-EV-VS-TOP CONTROL FAILED on {day} -> no output: {fails}; {st}')
    os.makedirs(OUTD, exist_ok=True)
    cols = ['n', 'shares'] + VCOLS
    pd.DataFrame([dict(day=int(day), who=k[0], src=k[1], depth=k[2], **dict(zip(cols, v))) for k, v in acc.items()]).to_parquet(
        f'{OUTD}/theirs_{day}.parquet', index=False)
    pd.DataFrame([dict(day=int(day), case=k[0], young=k[1], src=k[2], depth=k[3], **dict(zip(cols, v))) for k, v in ours.items()]).to_parquet(
        f'{OUTD}/ours_{day}.parquet', index=False)
    pd.DataFrame([dict(day=int(day), signer=k[0], src=k[1], **dict(zip(cols, v))) for k, v in pm.items()]).to_parquet(
        f'{OUTD}/top5_makers_{day}.parquet', index=False)
    st['seconds'] = time.time() - T0
    json.dump(st, open(f'{OUTD}/day_{day}.json', 'w'), indent=1, default=float)
    print(f'{day}: {st}', flush=True)


def report():
    selftest()
    S = {d: json.load(open(f'{OUTD}/day_{d}.json')) for d in DAYS}
    T = pd.concat([pd.read_parquet(f'{OUTD}/theirs_{d}.parquet') for d in DAYS], ignore_index=True)
    O = pd.concat([pd.read_parquet(f'{OUTD}/ours_{d}.parquet') for d in DAYS], ignore_index=True)
    PM = pd.concat([pd.read_parquet(f'{OUTD}/top5_makers_{d}.parquet') for d in DAYS], ignore_index=True)
    nd = float(len(DAYS)); win = sum(S[d]['windows'] for d in DAYS)
    tot = pd.read_csv(os.path.join(HERE, '..', 'reviews', 'strategy_scorecard_20261116', 'results_v1', 'strategy_totals.csv'))

    def row(x, label, k=1.0):
        q = float(x.shares.sum())
        c = {cc: float(x[cc].sum()) for cc in VCOLS}
        return (f'  {label:<34} {q / nd / k:10,.0f} | ' + ' '.join(f'{100 * c[cc] / q:+7.3f}' for cc in VCOLS) +
                f' | {c["markout_1000_usd"] / nd / k:+9.1f} {c["terminal_pnl_usd"] / nd / k:+9.1f} {c["settlement_pnl_usd"] / nd / k:+9.1f}')
    hdr = ('  who                                  sh a day | c/sh: spread  +100ms  +500ms     +1s     +5s  term60  settle | '
           '$ a day: +1s  term60  settle')
    asof = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    st = {k: sum(S[d][k] for d in DAYS) for k in ('windows', 'boundary_windows', 'imputed_legs', 'legs', 'no_pre_mid', 'no_mark', 'parity_fills',
                                                  'parity_bad', 'topc_legs')}
    L = [f'STOP-EV vs TOP MAKERS (POST HOC, descriptive): the scorecard\'s STOP_EV (simulated) against the real makers, the same {win} first-minute '
         f'windows on 5 consumed dates; as of {asof}',
         f'controls: value parity on {st["parity_fills"]:,} scorecard fills ({st["parity_bad"]} differ); planted errors caught on every day '
         f'(fills flagged: ' + ', '.join(f'{nm} {sum(S[d]["mutations"][nm] for d in DAYS):,}' for nm in S[DAYS[0]]['mutations']) + '); '
         f'imputed legs {st["imputed_legs"]:,} = STOP-EV-PLAY v2; TOP-COMPARE sums reproduced on ' +
         ', '.join(d for d in DAYS if isinstance(S[d]['topc'], dict)) + f'; maker legs {st["legs"]:,} (no pre-fill mid {st["no_pre_mid"]}, '
         f'not valued {st["no_mark"]})', '',
         'PART 1: per day (5-date mean), all depths. c / share by horizon (term60 = the 60.2 s mark; settle = held to resolution)', hdr]
    for case, lab in (('STOP_EV__recorded58', 'STOP_EV recorded58, all fills'), ('STOP_EV__legacy40', 'STOP_EV legacy40, all fills')):
        x = O[O.case == case]; L.append(row(x, lab)); L.append(row(x[~x.young], lab.replace('all fills', 'age >= 100 ms')))
        L.append(row(x[(~x.young) & (x.src == 'WS')], lab.replace('all fills', 'WS & age >= 100 ms')))
    for who in GROUPS:
        x = T[T.who == who]; L.append(row(x, f'{who} (real)')); L.append(row(x[x.src == 'WS'], f'{who} (real), WS-timed'))
    L.append(row(T[T.who == 'top 5'], 'top 5 (real), per maker', 5.0))
    L += ['', 'PART 2: by depth at the fill (all sources): share of shares | c/sh +1 s | c/sh term60 | c/sh settle   (ours: recorded58)']
    for dc in ('at best', '1 behind', '2+ behind', 'inside', 'no frame'):
        parts = []
        for nm, x in (('STOP_EV all', O[O.case == 'STOP_EV__recorded58']), ('STOP_EV >=100ms', O[(O.case == 'STOP_EV__recorded58') & ~O.young]),
                      ('top 5', T[T.who == 'top 5']), ('6-20', T[T.who == '6-20']), ('rest', T[T.who == 'rest'])):
            q0 = float(x.shares.sum()); y_ = x[x.depth == dc]; q = float(y_.shares.sum())
            if q <= 0:
                parts.append(f'{nm} -'); continue
            parts.append(f'{nm} {q / q0:5.1%} {100 * y_.markout_1000_usd.sum() / q:+6.3f} {100 * y_.terminal_pnl_usd.sum() / q:+6.3f} '
                         f'{100 * y_.settlement_pnl_usd.sum() / q:+6.3f}')
        L.append(f'  {dc:<9}: ' + ' | '.join(parts))
    L += ['', 'PART 3: per day: shares | +1 s $ | term60 $ | settle $   (ours recorded58 all fills; top 5 real)']
    for d in DAYS:
        x = O[(O.case == 'STOP_EV__recorded58') & (O.day == int(d))]; y_ = T[(T.who == 'top 5') & (T.day == int(d))]
        L.append(f'  {d}: STOP_EV {x.shares.sum():8,.0f} {x.markout_1000_usd.sum():+8.1f} {x.terminal_pnl_usd.sum():+8.1f} {x.settlement_pnl_usd.sum():+8.1f}'
                 f' | top 5 {y_.shares.sum():10,.0f} {y_.markout_1000_usd.sum():+9.1f} {y_.terminal_pnl_usd.sum():+9.1f} {y_.settlement_pnl_usd.sum():+9.1f}')
    pmg = PM.groupby(['day', 'signer'])[['shares'] + VCOLS].sum().reset_index()
    L += ['', 'PART 4: each top-5 maker-day (ids per day): shares | c/sh +1 s | term60 | settle']
    for d in DAYS:
        x = pmg[pmg.day == int(d)].sort_values('shares', ascending=False)
        L.append(f'  {d}: ' + ' | '.join(f'{r.shares:9,.0f} {100 * r.markout_1000_usd / r.shares:+6.3f} {100 * r.terminal_pnl_usd / r.shares:+6.3f} '
                                         f'{100 * r.settlement_pnl_usd / r.shares:+6.3f}' for r in x.itertuples()))
    ck = tot.set_index(tot.columns[0]) if 'case' not in tot.columns else tot.set_index('case')
    x = O[O.case == 'STOP_EV__recorded58']
    L += ['', f'reconciliation with the scorecard totals (STOP_EV recorded58, 5 dates): shares {x.shares.sum():,.2f} | terminal $ '
          f'{x.terminal_pnl_usd.sum():+.2f} | settlement $ {x.settlement_pnl_usd.sum():+.2f}   (strategy_totals.csv: '
          + ', '.join(f'{c} {ck.loc["STOP_EV__recorded58", c]}' for c in ('shares', 'terminal_pnl_usd', 'settlement_pnl_usd') if c in ck.columns) + ')']
    os.makedirs(OUTD, exist_ok=True)
    open(f'{OUTD}/stop_ev_vs_top.txt', 'w').write('\n'.join(L) + '\n')
    print('\n'.join(L), flush=True)


if __name__ == '__main__':
    cmd = sys.argv[1] if len(sys.argv) > 1 else ''
    if cmd == 'selftest':
        selftest()
    elif cmd == 'day':
        day_run(sys.argv[2])
    elif cmd == 'report':
        report()
    else:
        sys.exit('usage: pf_stop_ev_vs_top.py selftest | day <day> | report')
